public Person() {
    this("No name yet");        // calls the other constructor in this class
}

public Person(String initialName) {
    name = initialName;
}

public class Undergraduate extends Student {
    private int level;

    public Undergraduate(String name, int studentNumber, int level) {
        super(name, studentNumber);     // must be first
        this.level = level;
    }

    @Override
    public void writeOutput() {
        super.writeOutput();            // reuse the parent's version, then add to it
        System.out.println("Student Level: " + level);
    }
}
